# region: digest
def digest(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: shape
def shape(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: fold
def fold(xs):
    return [v for v in xs if v % 2 == 0]

# region: render
def render(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: sift
def sift(xs):
    n = len(xs) - 1
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: intake
def intake(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return intake(sift(render(fold(shape(digest(raw))))))

